UPDATE
    account
SET
    updated_at = CURRENT_TIMESTAMP

    ,roles = JSON_ARRAY(${roleNmsStr})


    ,department_id = #{departmentId}


    ,teams = JSON_ARRAY(${teamsStr})

WHERE
    1 = 1

    AND id = #{id}


    AND (
        account = #{account}
        OR phone = #{account}
        OR email = #{account}
    )

UPDATE
    account
SET
    updated_at = CURRENT_TIMESTAMP


    ,deleted_at = CURRENT_TIMESTAMP


    ,deleted_at = NULL


WHERE
    1 = 1

    AND id = #{accountInfo.id}


    AND (
        account = #{accountInfo.account}
        OR phone = #{accountInfo.account}
        OR email = #{accountInfo.account}
    )

