INSERT INTO role ( id ,name
,auth_cd
) SELECT UUID() ,#{roleInfo.name}
,#{roleInfo.authCd}
WHERE NOT EXISTS ( SELECT 0 FROM role WHERE name = #{roleInfo.name} )

