UPDATE
    role
SET
    id = #{roleInfo.id}

    ,name = #{roleInfo.name}


    ,auth_cd = #{roleInfo.authCd}

WHERE
    id = #{roleInfo.id}

mapper.select:
SELECT d.id AS id, d.name AS name, d.parent_id AS parentId, fp.pid AS fullpath, d.leader AS leader, DATE_FORMAT(d.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, DATE_FORMAT(d.updated_at, '%Y-%m-%d %H:%i:%s') AS updatedAt FROM department d, JSON_TABLE( d.fullpath, '$[*]' COLUMNS (pid varchar(255) PATH '$') ) fp WHERE d.id = #{id}
AND d.deleted_at IS NOT NULL
AND d.deleted_at IS NULL

