    department
SET
    updated_at = CURRENT_TIMESTAMP

    ,name = #{departmentInfo.name}


    ,parent_id = #{departmentInfo.parentId}


    ,fullpath = JSON_ARRAY(${departmentInfo.fullpaths})


    ,leader = #{departmentInfo.leader}

WHERE
    id = #{departmentInfo.id}
